describe('renderGenericSections job eviction', () => {
  const blocks = [
    jobSalience('job:fresh', jobEvents('job:fresh', 10, 1 * DAY_MS)),
    jobSalience('job:old1', jobEvents('job:old1', 20, 10 * DAY_MS)),
    jobSalience('job:old2', jobEvents('job:old2', 30, 11 * DAY_MS)),
  ];

  it('with referenceTimestamp drops aged-out jobs below the floor', () => {
    // floorN default is 10, so all 3 survive the floor regardless of age.
    // Use a render where floor cannot rescue: build > floor old jobs.
    const many = [
      jobSalience('job:fresh', jobEvents('job:fresh', 1000, 1 * DAY_MS)),
      ...Array.from({ length: 12 }, (_, i) =>
        jobSalience(`job:old${i}`, jobEvents(`job:old${i}`, 100 + i * 2, (10 + i) * DAY_MS))
      ),
    ];
    const out = renderGenericSections({
      blocks: many,
      scheduler: { alarmsPending: 0, remindersPending: 0 },
      referenceTimestamp: NOW,
    });
    expect(out).toContain('job:fresh');
    // The 10 highest-seq old jobs are kept by the floor; the 2 lowest-seq drop.
    // old0/old1 have the lowest seqs → dropped.
    expect(out).not.toContain('job:old0 ');
    expect(out).not.toContain('job:old1 ');
    expect(out).toContain('job:old11');
  });

  it('without referenceTimestamp renders all jobs (backward)', () => {
    const out = renderGenericSections({
      blocks,
      scheduler: { alarmsPending: 0, remindersPending: 0 },
    });
    expect(out).toContain('job:fresh');
    expect(out).toContain('job:old1');
    expect(out).toContain('job:old2');
  });
});

// ABOUTME: Shared test setup for agent tests
// ABOUTME: Provides unified setup that handles temp LACE_DIR and registered cleanup tasks

import { useTempLaceDir, type TempLaceDirContext } from './temp-lace-dir';
import { beforeEach, afterEach } from 'vitest';

export interface EnhancedTempLaceDirContext extends TempLaceDirContext {
  /** Register a cleanup function to be called in afterEach */
  registerCleanup: (fn: () => void | Promise<void>) => void;
}

/**
 * Complete test setup for agent tests - handles temp LACE_DIR isolation and persistence reset
 * Use this instead of manually calling useTempLaceDir() and setupTestPersistence()
 *
 * Persistence automatically initializes to ${LACE_DIR}/lace.db on first use via getPersistence()
 *
 * @returns Enhanced TempLaceDirContext with cleanup registry for tests that need access to the temp directory
 */
export function setupCoreTest(): EnhancedTempLaceDirContext {
  const tempLaceDir = useTempLaceDir();
  const cleanupTasks: (() => void | Promise<void>)[] = [];

  beforeEach(() => {
    cleanupTasks.length = 0; // Reset cleanup tasks
  });

  // Run all registered cleanup tasks after each test
  afterEach(async () => {
    for (const cleanup of cleanupTasks) {
      try {
        await cleanup();
      } catch (error) {
        console.warn('Cleanup task failed:', error);
      }
    }
  });

  return {
    get tempDir() {
      return tempLaceDir.tempDir;
    },
    get originalLaceDir() {
      return tempLaceDir.originalLaceDir;
    },
    set originalLaceDir(value: string | undefined) {
      tempLaceDir.originalLaceDir = value;
    },
    registerCleanup: (fn: () => void | Promise<void>) => cleanupTasks.push(fn),
  };
}

// ABOUTME: Unit tests for composeAndWriteSystemPromptSet's skip-if-unchanged
// ABOUTME: behavior — re-rendering an identical persona prompt appends nothing.

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { PassThrough } from 'node:stream';
import { createNdjsonStdioTransport, JsonRpcPeer } from '@lace/ent-protocol';
import {
  createAgentServerState,
  registerAgentRpcMethods,
  createToolExecutorForMode,
} from '../../../server';
import { defaultInitializeParams } from '../../../__tests__/helpers/initialize';
import { getSessionDir, readSessionState } from '@lace/agent/storage/session-store';
import { readDurableEvents } from '@lace/agent/storage/event-log';
import { composeAndWriteSystemPromptSet, rerenderPersonaForSession } from '../session';
import { buildProviderMessagesFromDurableEvents } from '@lace/agent/message-building/message-builder';
import { logger } from '@lace/agent/utils/logger';

function systemPromptTexts(sessionDir: string): string[] {
  const events = readDurableEvents(sessionDir, { limit: Number.MAX_SAFE_INTEGER }).events as Array<{
    type: string;
    data?: { text?: string };
  }>;
  return events.filter((e) => e.type === 'system_prompt_set').map((e) => e.data?.text ?? '');
}

describe('composeAndWriteSystemPromptSet — skip-if-unchanged', () => {
  let originalLaceDir: string | undefined;
  let originalTestProvider: string | undefined;
  let tempDir: string;
  let workDir: string;

  beforeEach(() => {
    originalLaceDir = process.env.LACE_DIR;
    originalTestProvider = process.env.LACE_AGENT_TEST_PROVIDER;
    tempDir = mkdtempSync(join(tmpdir(), 'lace-compose-sps-'));
    workDir = mkdtempSync(join(tmpdir(), 'lace-compose-sps-wd-'));
    process.env.LACE_DIR = tempDir;
    process.env.LACE_AGENT_TEST_PROVIDER = '1';
  });

  afterEach(() => {
    if (originalLaceDir === undefined) delete process.env.LACE_DIR;
    else process.env.LACE_DIR = originalLaceDir;
    if (originalTestProvider === undefined) delete process.env.LACE_AGENT_TEST_PROVIDER;
    else process.env.LACE_AGENT_TEST_PROVIDER = originalTestProvider;
    rmSync(tempDir, { recursive: true, force: true });
    rmSync(workDir, { recursive: true, force: true });
  });

  it('does not append a second event when re-rendering the same persona prompt', async () => {
    const state = createAgentServerState();
    const aToB = new PassThrough();
    const bToA = new PassThrough();
    const client = new JsonRpcPeer(createNdjsonStdioTransport({ readable: bToA, writable: aToB }), {
      idPrefix: 'c_',
    });
    const server = new JsonRpcPeer(createNdjsonStdioTransport({ readable: aToB, writable: bToA }), {
      idPrefix: 'a_',
    });
    registerAgentRpcMethods(server, state);

    try {
      await client.request('initialize', defaultInitializeParams());
      const { sessionId } = (await client.request('session/new', {
        cwd: workDir,
        mcpServers: [],
        persona: 'lace',
      })) as { sessionId: string };
      const sessionDir = getSessionDir(sessionId);

      // session/new already wrote exactly one system_prompt_set.
      const afterNew = systemPromptTexts(sessionDir);
      expect(afterNew.length).toBe(1);
      const personaPrompt = afterNew[0]!;

      // Re-render with the SAME persona/cwd → byte-identical prompt → no append.
      await composeAndWriteSystemPromptSet({
        sessionDir,
        sessionState: readSessionState(sessionDir),
        persona: 'lace',
        cwd: workDir,
        state,
        createToolExecutorForMode,
      });

      const afterRerender = systemPromptTexts(sessionDir);
      expect(afterRerender.length).toBe(1);
      expect(afterRerender[0]).toBe(personaPrompt);

      // A second identical re-render still appends nothing.
      await composeAndWriteSystemPromptSet({
        sessionDir,
        sessionState: readSessionState(sessionDir),
        persona: 'lace',
        cwd: workDir,
        state,
        createToolExecutorForMode,
      });
      expect(systemPromptTexts(sessionDir).length).toBe(1);
    } finally {
      client.close();
      server.close();
    }
  });

  it('appends a new event when the rendered prompt changes (different cwd)', async () => {
    const state = createAgentServerState();
    const aToB = new PassThrough();
    const bToA = new PassThrough();
    const client = new JsonRpcPeer(createNdjsonStdioTransport({ readable: bToA, writable: aToB }), {
      idPrefix: 'c_',
    });
    const server = new JsonRpcPeer(createNdjsonStdioTransport({ readable: aToB, writable: bToA }), {
      idPrefix: 'a_',
    });
    registerAgentRpcMethods(server, state);

    const otherWorkDir = mkdtempSync(join(tmpdir(), 'lace-compose-sps-wd2-'));

    try {
      await client.request('initialize', defaultInitializeParams());
      const { sessionId } = (await client.request('session/new', {
        cwd: workDir,
        mcpServers: [],
        persona: 'lace',
      })) as { sessionId: string };
      const sessionDir = getSessionDir(sessionId);

      const afterNew = systemPromptTexts(sessionDir);
      expect(afterNew.length).toBe(1);

      // Re-render with a DIFFERENT cwd → the prompt embeds the new cwd → it
      // differs from the latest event → a new system_prompt_set is appended.
      await composeAndWriteSystemPromptSet({
        sessionDir,
        sessionState: readSessionState(sessionDir),
        persona: 'lace',
        cwd: otherWorkDir,
        state,
        createToolExecutorForMode,
      });

      const after = systemPromptTexts(sessionDir);
      expect(after.length).toBe(2);
      expect(after[1]).not.toBe(after[0]);
    } finally {
      client.close();
      server.close();
      rmSync(otherWorkDir, { recursive: true, force: true });
    }
  });

  it('rebuild after a persona rerender uses the latest prompt without an invariant warning', async () => {
    const state = createAgentServerState();
    const aToB = new PassThrough();
    const bToA = new PassThrough();
    const client = new JsonRpcPeer(createNdjsonStdioTransport({ readable: bToA, writable: aToB }), {
      idPrefix: 'c_',
    });
    const server = new JsonRpcPeer(createNdjsonStdioTransport({ readable: aToB, writable: bToA }), {
      idPrefix: 'a_',
    });
    registerAgentRpcMethods(server, state);
    const otherWorkDir = mkdtempSync(join(tmpdir(), 'lace-compose-sps-wd3-'));
    const warnSpy = vi.spyOn(logger, 'warn');

    try {
      await client.request('initialize', defaultInitializeParams());
      const { sessionId } = (await client.request('session/new', {
        cwd: workDir,
        mcpServers: [],
        persona: 'lace',
      })) as { sessionId: string };
      const sessionDir = getSessionDir(sessionId);

      // A different cwd makes the rendered prompt differ, so the rerender appends.
      await rerenderPersonaForSession({
        sessionDir,
        persona: 'lace',
        cwd: otherWorkDir,
        state,
        createToolExecutorForMode,
      });

      const texts = systemPromptTexts(sessionDir);
      expect(texts.length).toBe(2);
      expect(texts[1]).not.toBe(texts[0]);

      warnSpy.mockClear();
      const { systemPrompt } = buildProviderMessagesFromDurableEvents(sessionDir);
      expect(systemPrompt).toBe(texts[1]);
      const invariantWarns = warnSpy.mock.calls.filter((args) =>
        String(args[0] ?? '').includes('invariant violation')
      );
      expect(invariantWarns).toEqual([]);
    } finally {
      warnSpy.mockRestore();
      client.close();
      server.close();
      rmSync(otherWorkDir, { recursive: true, force: true });
    }
  });
});

// ABOUTME: PRI-2943 — a compaction that cannot fit the window must be reported as
// ABOUTME: unrecoverable, not retried forever as if it had succeeded.

import { describe, it, expect } from 'vitest';
import type { CompactResult } from '../types';
// Does not exist yet. The postcondition compaction never had.
import { assessCompactionProgress } from '../strategy';

// ---------------------------------------------------------------------------
// `validatePreserved` checks that the result is structurally sound and that is
// all. cadence-sen's emergency compactions all passed it while emitting a
// prefix larger than the window, so the runner retried, re-assembled a
// multi-megabyte context, and eventually exhausted the 2GB node heap. Thirty-two
// times. The container reported `Up (healthy)` throughout and Slack events kept
// queueing, so from outside she looked idle rather than broken.
//
// The missing postcondition is not "did it produce valid output" but "did it
// make the session runnable". A compaction that cannot is a terminal state and
// needs to say so once, loudly, rather than fail silently on a loop.
// ---------------------------------------------------------------------------

const CONTEXT_WINDOW = 1_000_000;

const resultOfSize = (chars: number): CompactResult =>
  ({
    compactionEvent: {
      type: 'context_compacted',
      data: {
        type: 'context_compacted',
        strategy: 'track-based',
        messagesCompacted: 13957,
        preserved: [{ role: 'user', content: 'x'.repeat(chars) }],
      },
    },
  }) as unknown as CompactResult;

describe('assessCompactionProgress (PRI-2943)', () => {
  it('accepts a compaction that leaves the session comfortably runnable', () => {
    const verdict = assessCompactionProgress(resultOfSize(200_000), {
      contextWindow: CONTEXT_WINDOW,
      inputChars: 8_000_000,
    });
    expect(verdict.ok).toBe(true);
  });

  it('rejects a compaction whose own output exceeds the window', () => {
    const verdict = assessCompactionProgress(resultOfSize(4_400_000), {
      contextWindow: CONTEXT_WINDOW,
      inputChars: 8_000_000,
    });
    expect(verdict.ok).toBe(false);
  });

  it('marks an over-window result unrecoverable rather than retryable', () => {
    const verdict = assessCompactionProgress(resultOfSize(4_400_000), {
      contextWindow: CONTEXT_WINDOW,
      inputChars: 8_000_000,
    });
    expect(verdict.retryable).toBe(false);
  });

  it('rejects a compaction that did not shrink its input', () => {
    const verdict = assessCompactionProgress(resultOfSize(500_000), {
      contextWindow: CONTEXT_WINDOW,
      inputChars: 500_000,
    });
    expect(verdict.ok).toBe(false);
  });

  it('explains itself with the numbers an operator needs', () => {
    const verdict = assessCompactionProgress(resultOfSize(4_400_000), {
      contextWindow: CONTEXT_WINDOW,
      inputChars: 8_000_000,
    });
    expect(verdict.reason).toBeTruthy();
    expect(String(verdict.reason)).toMatch(/\d/);
  });

  it('passes through when no context window is known', () => {
    const verdict = assessCompactionProgress(resultOfSize(4_400_000), {
      inputChars: 8_000_000,
    });
    expect(verdict.ok).toBe(true);
  });
});

import { toNonEmptyString } from '@lace/agent/rpc/utils';
import { readAllSessionEventLines } from './event-log';

export type PendingPermissionRecord = {
  toolCallId: string;
  turnId: string;
  turnSeq: number;
  jobId?: string;
  tool: string;
  kind?: string;
  resource: string;
  options: Array<{ optionId: string; label: string }>;
  requestedAt: string;
  input: Record<string, unknown>;
};

type DurableEventLine = {
  type?: string;
  turnId?: unknown;
  turnSeq?: unknown;
  data?: Record<string, unknown>;
};

function toFiniteNumber(value: unknown): number | null {
  if (typeof value !== 'number' || !Number.isFinite(value)) return null;
  return value;
}

// Define the expected shape for option items
type OptionItem = { optionId?: unknown; label?: unknown };

function toOptions(value: unknown): Array<{ optionId: string; label: string }> | null {
  if (!Array.isArray(value)) return null;
  const parsed: Array<{ optionId: string; label: string }> = [];
  for (const item of value) {
    if (!item || typeof item !== 'object') return null;
    const itemObj = item as OptionItem;
    const optionId = toNonEmptyString(itemObj.optionId);
    const label = typeof itemObj.label === 'string' ? itemObj.label : null;
    if (!optionId || label === null) return null;
    parsed.push({ optionId, label });
  }
  return parsed;
}

export function derivePendingPermissionsFromDurableEvents(
  sessionDir: string
): PendingPermissionRecord[] {
  const pendingByToolCallId = new Map<string, PendingPermissionRecord>();

  for (const line of readAllSessionEventLines(sessionDir)) {
    try {
      const parsed = JSON.parse(line) as DurableEventLine;

      if (parsed.type === 'permission_requested') {
        const turnId = toNonEmptyString(parsed.turnId);
        const turnSeq = toFiniteNumber(parsed.data?.turnSeq);
        const toolCallId = toNonEmptyString(parsed.data?.toolCallId);
        const tool = toNonEmptyString(parsed.data?.tool);
        const resource = toNonEmptyString(parsed.data?.resource);
        const requestedAt = toNonEmptyString(parsed.data?.requestedAt);
        const options = toOptions(parsed.data?.options);
        const input =
          parsed.data?.input && typeof parsed.data.input === 'object'
            ? (parsed.data.input as Record<string, unknown>)
            : null;
        if (!turnId || turnSeq === null || !toolCallId || !tool || !resource || !requestedAt)
          continue;
        if (!options || !input) continue;

        const jobId = toNonEmptyString(parsed.data?.jobId) ?? undefined;
        const kind = toNonEmptyString(parsed.data?.kind) ?? undefined;

        pendingByToolCallId.set(toolCallId, {
          toolCallId,
          turnId,
          turnSeq,
          jobId,
          tool,
          kind,
          resource,
          options,
          requestedAt,
          input,
        });
        continue;
      }

      if (
        parsed.type === 'permission_decided' ||
        parsed.type === 'permission_cancelled' ||
        parsed.type === 'tool_use'
      ) {
        const toolCallId =
          parsed.type === 'tool_use'
            ? toNonEmptyString(parsed.data?.toolCallId)
            : toNonEmptyString(parsed.data?.toolCallId);

        if (toolCallId) pendingByToolCallId.delete(toolCallId);
      }
    } catch {
      // ignore malformed lines
    }
  }

  return [...pendingByToolCallId.values()];
}

// ABOUTME: The toolkit is imported across checkouts by plugin strategies, so its
// ABOUTME: header promises it is self-contained. That promise is only worth
// ABOUTME: anything if something checks it: a stray import of the storage layer
// ABOUTME: drags better-sqlite3 (a native module) in behind it, and a plugin
