// ABOUTME: PRI-2943 — compaction must make progress: strictly smaller than its input,
// ABOUTME: and never larger on a second pass over its own output.

import { describe, it, expect } from 'vitest';
import type { DurableEventData, TypedDurableEvent } from '@lace/agent/storage/event-types';
import { compact } from '../track-compaction';

// ---------------------------------------------------------------------------
// The wedge this prevents.
//
// cadence-sen ran ten consecutive emergency compactions on 2026-08-24 with
// `messagesCompacted` frozen at 13,957 and the resulting request pinned at
// ~1,010,063 tokens against a 1,000,000 window. Compaction "succeeded" every
// time — it produced a structurally valid result — while making no progress at
// all, because the compacted prefix it emitted was itself larger than the
// window and the strategy had no way to shrink it further.
//
// Structural validity was the only postcondition anyone checked. These tests
// add the two that matter: output smaller than input, and no growth across
// passes.
// ---------------------------------------------------------------------------

const CONTEXT_WINDOW = 1_000_000;
const CHARS_PER_TOKEN = 4;

const event = (
  seq: number,
  type: DurableEventData['type'],
  data: Record<string, unknown>,
  turnId?: string
): TypedDurableEvent => ({
  eventSeq: seq,
  timestamp: new Date(Date.parse('2026-06-01T00:00:00Z') + seq * 1000).toISOString(),
  ...(turnId ? { turnId } : {}),
  type,
  data: { type, ...data } as TypedDurableEvent['data'],
});

/**
 * A session shaped like cadence's: thousands of turns of chatty
 * notification-and-reply traffic, none of it individually large.
 */
function longSession(turns: number, startSeq = 0): TypedDurableEvent[] {
  const events: TypedDurableEvent[] = [];
  let seq = startSeq;
  for (let i = 0; i < turns; i++) {
    const turnId = `turn_${i}`;
    events.push(event(seq++, 'turn_start', {}, turnId));
    events.push(
      event(seq++, 'prompt', {
        content: [{ type: 'text', text: `message ${i} from a human: ${'detail '.repeat(40)}` }],
      })
    );
    events.push(
      event(seq++, 'context_injected', {
        content: [
          {
            type: 'text',
            text: `<notification kind="job-completed">Your background job completed successfully (exit code 0). ${'padding '.repeat(30)}</notification>`,
          },
        ],
      })
    );
    events.push(
      event(seq++, 'message', { content: `reply ${i}: ${'reasoning '.repeat(40)}` }, turnId)
    );
    events.push(event(seq++, 'turn_end', { stopReason: 'end_turn' }, turnId));
  }
  return events;
}

const sizeOf = (events: TypedDurableEvent[]) => JSON.stringify(events).length;

function preservedSize(result: Awaited<ReturnType<typeof compact>>): number {
  if ('noop' in result) return 0;
  return JSON.stringify(result.compactionEvent.data.preserved).length;
}

describe('compaction makes progress (PRI-2943)', () => {
  it('emits a prefix smaller than the events it compacted', async () => {
    const events = longSession(1500);
    const result = await compact(events, {
      threadId: 'sess_progress',
      contextWindow: CONTEXT_WINDOW,
    });
    expect('noop' in result).toBe(false);
    expect(preservedSize(result)).toBeLessThan(sizeOf(events));
  });

  it('emits a prefix that fits the context window it was given', async () => {
    const events = longSession(3000);
    const result = await compact(events, { threadId: 'sess_fits', contextWindow: CONTEXT_WINDOW });
    expect('noop' in result).toBe(false);
    // Not merely "under the window" — under it with room for a real turn.
    expect(preservedSize(result) / CHARS_PER_TOKEN).toBeLessThan(CONTEXT_WINDOW * 0.8);
  });

  it('does not grow when compacting again over its own output', async () => {
    const first = longSession(1500);
    const firstResult = await compact(first, {
      threadId: 'sess_fixedpoint',
      contextWindow: CONTEXT_WINDOW,
    });
    expect('noop' in firstResult).toBe(false);
    if ('noop' in firstResult) return;

    // Replay as the runner does: the prior compaction event, then more traffic.
    const second = [
      ...first,
      { ...event(9_000, 'context_compacted', {}), data: firstResult.compactionEvent.data },
      ...longSession(200, 10_000),
    ] as TypedDurableEvent[];

    const secondResult = await compact(second, {
      threadId: 'sess_fixedpoint',
      contextWindow: CONTEXT_WINDOW,
    });
    expect('noop' in secondResult).toBe(false);
    expect(preservedSize(secondResult)).toBeLessThanOrEqual(preservedSize(firstResult) * 1.1);
  });

  it('still shrinks a session whose prior prefix is already over the window', async () => {
    // cadence's actual state: the carried summary alone exceeds the window.
    const oversizeSummary = '[Earlier conversation, compacted by track]\n' + 'x'.repeat(2_300_000);
    const events = [
      {
        ...event(0, 'context_compacted', {}),
        data: {
          type: 'context_compacted',
          strategy: 'track-based',
          messagesCompacted: 13957,
          preserved: [{ role: 'user', content: oversizeSummary }],
        },
      },
      ...longSession(100, 1),
    ] as TypedDurableEvent[];

    const result = await compact(events, {
      threadId: 'sess_wedged',
      contextWindow: CONTEXT_WINDOW,
    });
    expect('noop' in result).toBe(false);
    expect(preservedSize(result) / CHARS_PER_TOKEN).toBeLessThan(CONTEXT_WINDOW * 0.8);
  });
});

// ABOUTME: End-to-end test for the compaction-strategy-plugin example.
// ABOUTME: Loads through the real loader into real registries; asserts the strategy
// ABOUTME: resolves at the real consumption site and produces a valid CompactResult.

import { describe, it, expect, beforeEach } from 'vitest';
import { loadPlugins, registries, resetRegistriesForTest } from '@lace/agent/plugins';
import {
  registerBuiltinCompaction,
  resolveCompactionStrategy,
} from '@lace/agent/compaction/strategy';
import type { TypedDurableEvent } from '@lace/agent/storage/event-types';
import type { CompactionContext } from '@lace/agent/compaction/types';

// Resolves relative to loader.ts (src/plugins/loader.ts) — same pattern as the
// whole-system integration test and persona-aware-tool-plugin e2e test.
const PLUGIN_SPEC = './__examples__/compaction-strategy-plugin';

/** Minimal CompactionContext for tests (provider/agent/modelId all optional). */
const TEST_CTX: CompactionContext = {
  threadId: 'thread-test-1',
  sessionDir: '/tmp/test-session',
};

/** Build a minimal TypedDurableEvent for a given type and data payload. */
function makeEvent(
  seq: number,
  type: TypedDurableEvent['type'],
  data: Record<string, unknown>
): TypedDurableEvent {
  return {
    eventSeq: seq,
    timestamp: new Date(0).toISOString(),
    type,
    data: { type, ...data } as TypedDurableEvent['data'],
  };
}

describe('compaction-strategy-plugin — end-to-end', () => {
  beforeEach(async () => {
    resetRegistriesForTest();
    // Built-in compaction must register before plugins (dup→fatal).
    registerBuiltinCompaction();
    await loadPlugins(PLUGIN_SPEC);
  });

  // ── Registry / loader surface ─────────────────────────────────────────────

  it('strategy is recorded in the compaction registry with correct owner', () => {
    expect(registries.compaction.has('compaction-example/user-turns-only')).toBe(true);
    expect(registries.compaction.owner('compaction-example/user-turns-only')).toBe(
      'compaction-example'
    );
  });

  it('strategy resolves by name at the real consumption site', () => {
    const strategy = resolveCompactionStrategy('compaction-example/user-turns-only');
    expect(strategy.name).toBe('compaction-example/user-turns-only');
  });

  it('built-in track-based strategy still resolves after plugin load', () => {
    const builtin = resolveCompactionStrategy('track-based');
    expect(builtin.name).toBe('track-based');
  });

  // ── Strategy behaviour: real compact() calls ──────────────────────────────

  it('returns noop when no prompt events are present', async () => {
    const strategy = resolveCompactionStrategy('compaction-example/user-turns-only');
    const events: TypedDurableEvent[] = [
      makeEvent(1, 'turn_start', {}),
      makeEvent(2, 'message', { content: 'Hello from assistant' }),
      makeEvent(3, 'turn_end', { stopReason: 'end_turn', usage: { costUsd: 0 } }),
    ];

    const result = await strategy.compact(events, TEST_CTX);

    expect(result).toEqual({ noop: true });
  });

  it('returns a context_compacted event containing the preserved user turns', async () => {
    const strategy = resolveCompactionStrategy('compaction-example/user-turns-only');
    const events: TypedDurableEvent[] = [
      makeEvent(1, 'prompt', { content: [{ type: 'text', text: 'Hello, lace!' }] }),
      makeEvent(2, 'turn_start', {}),
      makeEvent(3, 'message', { content: 'Hi there!' }),
      makeEvent(4, 'turn_end', { stopReason: 'end_turn', usage: { costUsd: 0 } }),
      makeEvent(5, 'prompt', { content: [{ type: 'text', text: 'What can you do?' }] }),
    ];

    const result = await strategy.compact(events, TEST_CTX);

    // Must be a compactionEvent, not noop
    expect('compactionEvent' in result).toBe(true);
    if (!('compactionEvent' in result)) throw new Error('expected compactionEvent');

    const { compactionEvent } = result;
    expect(compactionEvent.type).toBe('context_compacted');
    expect(compactionEvent.data.type).toBe('context_compacted');
    expect(compactionEvent.data.strategy).toBe('compaction-example/user-turns-only');
    expect(compactionEvent.data.messagesCompacted).toBe(events.length);

    // mergePreservedAdjacent merges adjacent same-role (user) entries into one
    const { preserved } = compactionEvent.data;
    expect(Array.isArray(preserved)).toBe(true);
    // Two prompt events → two user entries → merged into one by mergePreservedAdjacent
    expect(preserved).toHaveLength(1);

    const first = preserved[0] as { role: string; content: unknown[] };
    expect(first.role).toBe('user');
    // Both content blocks should appear in the merged entry
    expect(first.content).toContainEqual({ type: 'text', text: 'Hello, lace!' });
    expect(first.content).toContainEqual({ type: 'text', text: 'What can you do?' });
  });

  it('drops empty prompt events and still produces valid output', async () => {
    const strategy = resolveCompactionStrategy('compaction-example/user-turns-only');
    const events: TypedDurableEvent[] = [
      makeEvent(1, 'prompt', { content: [] }), // empty — will be dropped by toolkit
      makeEvent(2, 'prompt', { content: [{ type: 'text', text: 'Keep me' }] }),
    ];

    const result = await strategy.compact(events, TEST_CTX);

    expect('compactionEvent' in result).toBe(true);
    if (!('compactionEvent' in result)) throw new Error('expected compactionEvent');

    const { preserved } = result.compactionEvent.data;
    expect(Array.isArray(preserved)).toBe(true);
    expect(preserved).toHaveLength(1);
    const entry = preserved[0] as { role: string; content: unknown[] };
    expect(entry.role).toBe('user');
    expect(entry.content).toContainEqual({ type: 'text', text: 'Keep me' });
  });

  it('returns noop when all prompt events are empty', async () => {
    const strategy = resolveCompactionStrategy('compaction-example/user-turns-only');
    const events: TypedDurableEvent[] = [
      makeEvent(1, 'prompt', { content: [] }),
      makeEvent(2, 'prompt', { content: [] }),
    ];

    const result = await strategy.compact(events, TEST_CTX);

    // All empty → mergePreservedAdjacent returns [] → strategy returns noop
    expect(result).toEqual({ noop: true });
  });
});

// ABOUTME: Tests that the initialize handler registers embedder-supplied credentialToolsPaths
// exec-dirs globally with trusted provenance, persists them on state, and that only a
// trusted-provenance registration forwards the credential broker socket to the binary.

import { describe, expect, it, beforeEach, afterEach } from 'vitest';
import { PassThrough } from 'node:stream';
import { mkdtempSync, rmSync, writeFileSync, chmodSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createNdjsonStdioTransport, JsonRpcPeer } from '@lace/ent-protocol';
import { createAgentServerState, registerAgentRpcMethods } from '../server';
import { defaultInitializeParams } from './helpers/initialize';
import { registries, resetRegistriesForTest } from '@lace/agent/plugins';
import { registerExecDirInto } from '../tools/exec/register-exec';
import { registerBuiltinTools } from '../tools/builtins';
import { ToolExecutor } from '../tools/executor';

// A tiny exec-tool that answers `lace-tool-schema` with a request_credential descriptor
// (declaring the credentials capability) and, on `lace-tool-invoke`, echoes back the
// context block it received so the test can inspect socket forwarding.
const FIXTURE_SCRIPT = `#!/usr/bin/env node
const mode = process.argv[2];
if (mode === 'lace-tool-schema') {
  process.stdout.write(JSON.stringify({
    name: 'request_credential',
    description: 'fixture credential exec-tool',
    inputSchema: { type: 'object', properties: {} },
    capabilities: ['credentials'],
  }));
  process.exit(0);
}
let buf = '';
process.stdin.on('data', (d) => { buf += d; });
process.stdin.on('end', () => {
  const env = JSON.parse(buf || '{}');
  process.stdout.write(JSON.stringify({ content: JSON.stringify(env.context ?? {}) }));
  process.exit(0);
});
`;

function makeFixtureDir(): string {
  const dir = mkdtempSync(join(tmpdir(), 'lace-cred-fixture-'));
  const bin = join(dir, 'request-credential');
  writeFileSync(bin, FIXTURE_SCRIPT);
  chmodSync(bin, 0o755);
  return dir;
}

function createPairedPeers(register: (peer: JsonRpcPeer) => void) {
  const aToB = new PassThrough();
  const bToA = new PassThrough();
  const clientTransport = createNdjsonStdioTransport({ readable: bToA, writable: aToB });
  const serverTransport = createNdjsonStdioTransport({ readable: aToB, writable: bToA });
  const client = new JsonRpcPeer(clientTransport, { idPrefix: 'c_' });
  const server = new JsonRpcPeer(serverTransport, { idPrefix: 'a_' });
  register(server);
  return { client, server };
}

describe('initialize credentialToolsPaths', () => {
  let originalLaceDir: string | undefined;
  let tempDir: string;
  let fixtureDir: string;

  beforeEach(() => {
    resetRegistriesForTest();
    originalLaceDir = process.env.LACE_DIR;
    tempDir = mkdtempSync(join(tmpdir(), 'lace-agent-credtools-'));
    process.env.LACE_DIR = tempDir;
    fixtureDir = makeFixtureDir();
  });

  afterEach(() => {
    if (originalLaceDir === undefined) delete process.env.LACE_DIR;
    else process.env.LACE_DIR = originalLaceDir;
    rmSync(tempDir, { recursive: true, force: true });
    rmSync(fixtureDir, { recursive: true, force: true });
    resetRegistriesForTest();
  });

  it('registers the dir globally, keeps the reserved name, and persists the paths', async () => {
    const state = createAgentServerState();
    const { client, server } = createPairedPeers((peer) => registerAgentRpcMethods(peer, state));

    // (a) initialize (which builds the tool executor) does NOT throw despite
    // request_credential being a reserved per-session builtin name.
    await client.request('initialize', {
      ...defaultInitializeParams(),
      credentialToolsPaths: [fixtureDir],
    });

    // (b) request_credential is registered in the global tool registry.
    expect(registries.tools.has('request_credential')).toBe(true);
    expect(registries.tools.owner('request_credential')).toBe('credential');

    // (d) the paths are persisted on state.
    expect(state.credentialToolsPaths).toEqual([fixtureDir]);

    client.close();
    server.close();
  });

  it('defaults credentialToolsPaths to [] when omitted', async () => {
    const state = createAgentServerState();
    const { client, server } = createPairedPeers((peer) => registerAgentRpcMethods(peer, state));

    await client.request('initialize', defaultInitializeParams());

    expect(state.credentialToolsPaths).toEqual([]);
    expect(registries.tools.has('request_credential')).toBe(false);

    client.close();
    server.close();
  });

  it('forwards the broker socket only when the dir is registered with trusted provenance', async () => {
    // (c) Trusted provenance forwards credentialBrokerSocket; untrusted does not,
    // even though the binary self-declares the credentials capability.
    const invokeAndReadContext = async (): Promise<Record<string, unknown>> => {
      const executor = new ToolExecutor();
      executor.registerAllAvailableTools();
      const tool = executor.getTool('request_credential');
      expect(tool).toBeDefined();
      const result = await executor.execute(
        { id: 't1', name: 'request_credential', arguments: {} },
        {
          activeSessionId: 'sess-1',
          persona: 'engineer',
          credentialBrokerSocket: '/run/cred.sock',
          roleEnvironment: 'prod',
        }
      );
      const text = result.content.map((b) => b.text ?? '').join('');
      return JSON.parse(text) as Record<string, unknown>;
    };

    resetRegistriesForTest();
    registerBuiltinTools();
    registerExecDirInto(fixtureDir, { owner: 'credential', trustedCredentialProvenance: true });
    const trustedCtx = await invokeAndReadContext();
    expect(trustedCtx.credentialBrokerSocket).toBe('/run/cred.sock');

    resetRegistriesForTest();
    registerBuiltinTools();
    registerExecDirInto(fixtureDir, { owner: 'credential' });
    const untrustedCtx = await invokeAndReadContext();
    expect(untrustedCtx.credentialBrokerSocket).toBeUndefined();
  });
});

// ABOUTME: Tests for buildCompactionContext — binds ctx.query to oneShotQuery and threads guidance
// ABOUTME: Verifies prompt→messages mapping, model defaulting, guidance passthrough, and connection guard

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { buildCompactionContext, buildCompactionContextForConnection } from '../build-context';
import { ProviderRegistry } from '@lace/agent/providers/registry';

describe('buildCompactionContext', () => {
  const BASE_OPTS = {
    threadId: 'thread-1',
    sessionDir: '/tmp/session',
    connectionId: 'conn-abc',
    modelId: 'claude-3-5-sonnet',
  };

  it('returns ctx with guidance set when provided', () => {
    const ctx = buildCompactionContext({ ...BASE_OPTS, guidance: 'focus on errors' });
    expect(ctx.guidance).toBe('focus on errors');
  });

  it('returns ctx with guidance undefined when not provided', () => {
    const ctx = buildCompactionContext(BASE_OPTS);
    expect(ctx.guidance).toBeUndefined();
  });

  it('ctx.query({prompt}) calls oneShotQuery with connectionId, default modelId, and mapped messages', async () => {
    const fakeOneShotQuery = vi.fn().mockResolvedValue({ text: 'result', usage: undefined });
    const ctx = buildCompactionContext(BASE_OPTS, { oneShotQuery: fakeOneShotQuery });

    const result = await ctx.query!({ prompt: 'hello world' });

    expect(result).toEqual({ text: 'result', usage: undefined });
    expect(fakeOneShotQuery).toHaveBeenCalledWith({
      connectionId: 'conn-abc',
      model: 'claude-3-5-sonnet',
      messages: [{ role: 'user', content: 'hello world' }],
      signal: undefined,
    });
  });

  it('ctx.query({prompt, model}) overrides the default modelId', async () => {
    const fakeOneShotQuery = vi.fn().mockResolvedValue({ text: 'ok', usage: undefined });
    const ctx = buildCompactionContext(BASE_OPTS, { oneShotQuery: fakeOneShotQuery });

    await ctx.query!({ prompt: 'test', model: 'cheap-model' });

    expect(fakeOneShotQuery).toHaveBeenCalledWith(
      expect.objectContaining({ model: 'cheap-model' })
    );
  });

  it('ctx.query({prompt, connectionId}) overrides the session connectionId', async () => {
    const fakeOneShotQuery = vi.fn().mockResolvedValue({ text: 'ok', usage: undefined });
    const ctx = buildCompactionContext(BASE_OPTS, { oneShotQuery: fakeOneShotQuery });

    await ctx.query!({ prompt: 'test', connectionId: 'conn-other', model: 'cheap-model' });

    expect(fakeOneShotQuery).toHaveBeenCalledWith(
      expect.objectContaining({ connectionId: 'conn-other', model: 'cheap-model' })
    );
  });

  it('ctx.query({connectionId}) without a model is rejected, not sent with the session model', async () => {
    const fakeOneShotQuery = vi.fn().mockResolvedValue({ text: 'ok', usage: undefined });
    const ctx = buildCompactionContext(BASE_OPTS, { oneShotQuery: fakeOneShotQuery });

    await expect(ctx.query!({ prompt: 'test', connectionId: 'conn-other' })).rejects.toThrow(
      'ctx.query: a connectionId override requires a model override'
    );
    expect(fakeOneShotQuery).not.toHaveBeenCalled();
  });

  it('ctx.query({messages}) passes non-empty messages through directly (bypassing prompt mapping)', async () => {
    const fakeOneShotQuery = vi.fn().mockResolvedValue({ text: 'ok', usage: undefined });
    const ctx = buildCompactionContext(BASE_OPTS, { oneShotQuery: fakeOneShotQuery });

    const messages = [
      { role: 'user' as const, content: 'a' },
      { role: 'assistant' as const, content: 'b' },
    ];
    await ctx.query!({ messages });

    expect(fakeOneShotQuery).toHaveBeenCalledWith(expect.objectContaining({ messages }));
  });

  it('ctx.query({messages: []}) treats empty messages as no-messages and falls back to prompt', async () => {
    const fakeOneShotQuery = vi.fn().mockResolvedValue({ text: 'ok', usage: undefined });
    const ctx = buildCompactionContext(BASE_OPTS, { oneShotQuery: fakeOneShotQuery });

    await ctx.query!({ messages: [], prompt: 'fallback prompt' });

    expect(fakeOneShotQuery).toHaveBeenCalledWith(
      expect.objectContaining({
        messages: [{ role: 'user', content: 'fallback prompt' }],
      })
    );
  });

  it('forwards AbortSignal to oneShotQuery', async () => {
    const fakeOneShotQuery = vi.fn().mockResolvedValue({ text: 'ok', usage: undefined });
    const ctx = buildCompactionContext(BASE_OPTS, { oneShotQuery: fakeOneShotQuery });
    const signal = new AbortController().signal;

    await ctx.query!({ prompt: 'x', signal });

    expect(fakeOneShotQuery).toHaveBeenCalledWith(expect.objectContaining({ signal }));
  });

  it('ctx has threadId and sessionDir set', () => {
    const ctx = buildCompactionContext(BASE_OPTS);
    expect(ctx.threadId).toBe('thread-1');
    expect(ctx.sessionDir).toBe('/tmp/session');
  });

  it('ctx.referenceTimestamp defaults to a valid ISO date string', () => {
    const ctx = buildCompactionContext(BASE_OPTS);
    expect(typeof ctx.referenceTimestamp).toBe('string');
    expect(Number.isNaN(Date.parse(ctx.referenceTimestamp!))).toBe(false);
  });

  it('ctx.referenceTimestamp is preserved when caller supplies it', () => {
    const ctx = buildCompactionContext({
      ...BASE_OPTS,
      referenceTimestamp: '2026-06-19T00:00:00.000Z',
    });
    expect(ctx.referenceTimestamp).toBe('2026-06-19T00:00:00.000Z');
  });

  it('ctx.query is absent when connectionId is falsy', () => {
    const ctx = buildCompactionContext({ ...BASE_OPTS, connectionId: undefined });
    expect(ctx.query).toBeUndefined();
  });

  it('ctx.query is absent when modelId is falsy', () => {
    const ctx = buildCompactionContext({ ...BASE_OPTS, modelId: undefined });
    expect(ctx.query).toBeUndefined();
  });

  it('ctx.query is absent when both connectionId and modelId are absent', () => {
    const ctx = buildCompactionContext({
      threadId: 'thread-1',
      sessionDir: '/tmp/session',
    });
    expect(ctx.query).toBeUndefined();
  });

  it('ctx.query is present when both connectionId and modelId are provided', () => {
    const fakeOneShotQuery = vi.fn().mockResolvedValue({ text: 'ok', usage: undefined });
    const ctx = buildCompactionContext(BASE_OPTS, { oneShotQuery: fakeOneShotQuery });
    expect(ctx.query).toBeDefined();
  });

  it('forwards contextWindow so the strategy can size its tail (PRI-2906)', () => {
    const ctx = buildCompactionContext({ ...BASE_OPTS, contextWindow: 200_000 });
    expect(ctx.contextWindow).toBe(200_000);
  });

  it('buildCompactionContextForConnection resolves the window and threads it in', async () => {
    // The composition is the unit under test. Before this existed, the resolve
    // and the build were two lines repeated in each RPC handler, and deleting
    // the window from either one passed the entire suite.
    const resolveContextWindow = vi.fn().mockResolvedValue(750_000);
    const ctx = await buildCompactionContextForConnection(BASE_OPTS, {
      oneShotQuery: vi.fn(),
      resolveContextWindow,
    });
    expect(resolveContextWindow).toHaveBeenCalledWith({
      connectionId: BASE_OPTS.connectionId,
      modelId: BASE_OPTS.modelId,
    });
    expect(ctx.contextWindow).toBe(750_000);
  });

  it('buildCompactionContextForConnection omits the window when it cannot be resolved', async () => {
    const ctx = await buildCompactionContextForConnection(BASE_OPTS, {
      oneShotQuery: vi.fn(),
      resolveContextWindow: vi.fn().mockResolvedValue(undefined),
    });
    expect('contextWindow' in ctx).toBe(false);
    // Everything else still arrives — a failed window lookup must not cost the
    // caller its query binding or its guidance.
    expect(ctx.query).toBeDefined();
    expect(ctx.threadId).toBe(BASE_OPTS.threadId);
  });

  it('omits contextWindow rather than forwarding undefined', () => {
    // exactOptionalPropertyTypes: a present-but-undefined key and an absent one
    // are different to a strategy that checks `in`, and the fallback path keys
    // on absence.
    const ctx = buildCompactionContext(BASE_OPTS);
    expect('contextWindow' in ctx).toBe(false);
  });
});

