// ABOUTME: PRI-2943 — size bounds on the generic (track-based) compaction renderer.
// ABOUTME: track-based is the universal fallback every session lands on when its
// ABOUTME: persona cannot be resolved, so its output must be bounded by construction.

import { describe, it, expect } from 'vitest';
import type { DurableEventData, TypedDurableEvent } from '@lace/agent/storage/event-types';
import { renderGenericSections, untrackedSalience, type TrackBlock } from '../toolkit';

// ---------------------------------------------------------------------------
// Why this file exists
//
// cadence-sen's compacted prefix reached 2,304,363 chars — ~1.01M tokens on its
// own, larger than the 1M window it had to fit inside. Compaction could only
// ever shed the 160KB of live tail around it, so every emergency pass produced
// the same over-limit request and the session could never recover.
//
// The block was `untrackedSalience` output joined by `renderGenericSections`:
// 4,056 `Assistant:` + 679 `User:` + 840 `Note:` lines. Each LINE was capped at
// 500 chars; the LINE COUNT was capped at nothing, and nothing evicted by age.
//
// The numbers below are deliberately far beyond any sane session so the
// assertions describe a hard ceiling rather than a tuning preference.
// ---------------------------------------------------------------------------

const PATHOLOGICAL_EVENTS = 5000;
const LONG_TEXT = 'x'.repeat(3000);

const event = (
  seq: number,
  type: DurableEventData['type'],
  data: Record<string, unknown>
): TypedDurableEvent => ({
  eventSeq: seq,
  timestamp: new Date(Date.parse('2026-06-01T00:00:00Z') + seq * 1000).toISOString(),
  type,
  data: { type, ...data } as TypedDurableEvent['data'],
});

/** A conversation track with far more turns than any bound should allow through. */
function pathologicalConversation(): TypedDurableEvent[] {
  const events: TypedDurableEvent[] = [];
  for (let i = 0; i < PATHOLOGICAL_EVENTS; i++) {
    events.push(
      event(i * 2, 'prompt', { content: [{ type: 'text', text: `prompt ${i} ${LONG_TEXT}` }] })
    );
    events.push(event(i * 2 + 1, 'message', { content: `reply ${i} ${LONG_TEXT}` }));
  }
  return events;
}

/** A ceiling generous enough that no legitimate session hits it. */
const PREFIX_CHAR_CEILING = 400_000;

describe('untrackedSalience is bounded (PRI-2943)', () => {
  it('caps total body size, not just per-line length', () => {
    const block = untrackedSalience('untracked', pathologicalConversation());
    expect(block.body.length).toBeLessThanOrEqual(PREFIX_CHAR_CEILING);
  });

  it('caps the number of rendered lines', () => {
    const block = untrackedSalience('untracked', pathologicalConversation());
    const lines = block.body.split('\n').filter((l) => l.trim().length > 0);
    expect(lines.length).toBeLessThan(PATHOLOGICAL_EVENTS);
  });

  it('keeps the most recent turns when it drops', () => {
    const block = untrackedSalience('untracked', pathologicalConversation());
    expect(block.body).toContain(`reply ${PATHOLOGICAL_EVENTS - 1}`);
  });

  it('says so when it dropped history, so the agent knows to recall', () => {
    const block = untrackedSalience('untracked', pathologicalConversation());
    expect(block.body.toLowerCase()).toMatch(/omitted|dropped|truncated|earlier|recall/);
  });

  it('leaves a small conversation completely intact', () => {
    const small: TypedDurableEvent[] = [
      event(0, 'prompt', { content: [{ type: 'text', text: 'hello' }] }),
      event(1, 'message', { content: 'hi back' }),
    ];
    const block = untrackedSalience('untracked', small);
    expect(block.body).toContain('User: hello');
    expect(block.body).toContain('Assistant: hi back');
  });
});

describe('renderGenericSections is bounded (PRI-2943)', () => {
  const bigBlock = (trackId: string, n: number): TrackBlock => ({
    trackId,
    body: `${trackId}\n${'y'.repeat(20_000)}`,
    estimatedTokens: 5000,
    lastActivityTs: new Date(Date.parse('2026-06-01T00:00:00Z') + n * 1000).toISOString(),
    lastSeq: n,
  });

  it('caps the whole rendered prefix regardless of how many blocks arrive', () => {
    const blocks = [
      ...Array.from({ length: 200 }, (_, i) => bigBlock(`system:notify-${i}`, i)),
      ...Array.from({ length: 200 }, (_, i) => bigBlock(`slack:C0/thread-${i}`, 200 + i)),
    ];
    const out = renderGenericSections({
      blocks,
      scheduler: { alarmsPending: 0, remindersPending: 0 },
      referenceTimestamp: '2026-06-08T00:00:00Z',
    });
    expect(out.length).toBeLessThanOrEqual(PREFIX_CHAR_CEILING);
  });

  it('evicts stale system blocks the way it already evicts stale job blocks', () => {
    const blocks = Array.from({ length: 200 }, (_, i) => bigBlock(`system:notify-${i}`, i));
    const out = renderGenericSections({
      blocks,
      scheduler: { alarmsPending: 0, remindersPending: 0 },
      referenceTimestamp: '2026-07-01T00:00:00Z', // every block is far past any horizon
    });
    expect(out).not.toContain('system:notify-0');
    expect(out).toContain(`system:notify-199`);
  });

  it('never grows without a referenceTimestamp either', () => {
    const blocks = Array.from({ length: 200 }, (_, i) => bigBlock(`other:${i}`, i));
    const out = renderGenericSections({
      blocks,
      scheduler: { alarmsPending: 0, remindersPending: 0 },
    });
    expect(out.length).toBeLessThanOrEqual(PREFIX_CHAR_CEILING);
  });

  it('renders a normal-sized set unchanged', () => {
    const out = renderGenericSections({
      blocks: [
        {
          trackId: 'job:abc',
          body: '- job:abc do a thing → ✓ completed',
          estimatedTokens: 10,
          lastActivityTs: '2026-06-01T00:00:00Z',
          lastSeq: 1,
        },
      ],
      scheduler: { alarmsPending: 0, remindersPending: 0 },
    });
    expect(out).toContain('## Subagent jobs');
    expect(out).toContain('- job:abc do a thing → ✓ completed');
  });
});

// ABOUTME: Tests resolveContextWindow — the manual-compaction path's answer to
// ABOUTME: "how big is this model's window", which decides how much history a
// ABOUTME: compaction keeps. Getting it wrong is silent: too small a number just
// ABOUTME: throws away more of the conversation than it needed to.

import { describe, it, expect, vi } from 'vitest';
import { resolveContextWindow } from '../context-window';
import { AIProvider, type ModelInfo } from '@lace/agent/providers/base-provider';

/**
 * Provider whose catalog knows a 1M model under a dated id, so a bare alias has
 * to be resolved to reach it — the shape that made the real bug.
 */
class CatalogProvider extends AIProvider {
  constructor(private readonly models: ModelInfo[]) {
    super();
  }
  get providerName(): string {
    return 'catalog-test';
  }
  getProviderInfo() {
    return { name: 'catalog-test', displayName: 'Catalog Test', requiresApiKey: false };
  }
  isConfigured(): boolean {
    return true;
  }
  override getAvailableModels(): ModelInfo[] {
    return this.models;
  }
  protected async _createResponseImpl() {
    throw new Error('not used');
  }
  protected async _createStreamingResponseImpl() {
    throw new Error('not used');
  }
}

const model = (id: string, contextWindow: number): ModelInfo => ({
  id,
  displayName: id,
  contextWindow,
  maxOutputTokens: 8192,
});

const MODELS = [model('claude-opus-4-5-20251101', 200_000), model('claude-opus-5', 1_000_000)];

function factoryFor(provider: AIProvider) {
  return vi.fn().mockResolvedValue(provider);
}

describe('resolveContextWindow', () => {
  it('returns the window of an exactly-named model', async () => {
    const createProviderForTurn = factoryFor(new CatalogProvider(MODELS));
    const window = await resolveContextWindow(
      { connectionId: 'conn', modelId: 'claude-opus-5' },
      { createProviderForTurn }
    );
    expect(window).toBe(1_000_000);
  });

  it('resolves a bare alias before looking the window up', async () => {
    // The bug this exists to prevent: the factory resolves 'haiku' internally but
    // never hands back what it resolved to, and the catalog lookup is an exact
    // match — so an unresolved alias found nothing and fell through to a 200K
    // default, silently sizing the tail for the wrong model.
    //
    // The window here is deliberately not 200K and not 1M, so neither the old
    // default nor a lucky guess can produce it: only actually resolving the
    // alias reaches this number.
    const createProviderForTurn = factoryFor(
      new CatalogProvider([model('claude-haiku-4-5-20251001', 512_000)])
    );
    const window = await resolveContextWindow(
      { connectionId: 'conn', modelId: 'haiku' },
      { createProviderForTurn }
    );
    expect(window).toBe(512_000);
  });

  it('resolves an alias to the same model the turn factory would build', async () => {
    // Whatever this returns has to describe the model the NEXT REQUEST will use,
    // not merely some model matching the alias — otherwise the budget is sized
    // against a window the session never had. resolveModelAlias ranks by the
    // date embedded in the id, so an undated id loses to a dated one; agreeing
    // with that is the contract, even where the ranking is surprising.
    const createProviderForTurn = factoryFor(new CatalogProvider(MODELS));
    const window = await resolveContextWindow(
      { connectionId: 'conn', modelId: 'opus' },
      { createProviderForTurn }
    );
    expect(window).toBe(200_000); // claude-opus-4-5-20251101 outranks claude-opus-5
  });

  it('says it does not know rather than reporting a default as fact', async () => {
    // A model absent from the catalog must not come back as 200K — the caller
    // applies its own conservative assumption, and a wrong confident number is
    // worse than an admitted absence.
    const createProviderForTurn = factoryFor(new CatalogProvider(MODELS));
    const window = await resolveContextWindow(
      { connectionId: 'conn', modelId: 'some-model-we-never-shipped' },
      { createProviderForTurn }
    );
    expect(window).toBeUndefined();
  });

  it('returns undefined without a connection or model to resolve from', async () => {
    const createProviderForTurn = factoryFor(new CatalogProvider(MODELS));
    expect(
      await resolveContextWindow(
        { connectionId: undefined, modelId: 'claude-opus-5' },
        {
          createProviderForTurn,
        }
      )
    ).toBeUndefined();
    expect(
      await resolveContextWindow(
        { connectionId: 'conn', modelId: undefined },
        {
          createProviderForTurn,
        }
      )
    ).toBeUndefined();
    // No provider is built when there is nothing to build one from.
    expect(createProviderForTurn).not.toHaveBeenCalled();
  });

  it('survives a provider that cannot be created', async () => {
    // Missing credentials or an unknown instance must degrade a compaction, not
    // fail it — the compaction is still worth running on an assumed window.
    const createProviderForTurn = vi.fn().mockRejectedValue(new Error('no such instance'));
    const window = await resolveContextWindow(
      { connectionId: 'conn', modelId: 'claude-opus-5' },
      { createProviderForTurn }
    );
    expect(window).toBeUndefined();
  });

  it('always cleans the provider up, on both the success and failure paths', async () => {
    // It owns the provider's whole lifecycle like oneShotQuery does; leaking one
    // per manual compaction would leak an SDK client per /compact.
    const provider = new CatalogProvider(MODELS);
    const cleanup = vi.fn().mockResolvedValue(undefined);
    (provider as unknown as { cleanup: () => Promise<void> }).cleanup = cleanup;

    await resolveContextWindow(
      { connectionId: 'conn', modelId: 'claude-opus-5' },
      { createProviderForTurn: factoryFor(provider) }
    );
    expect(cleanup).toHaveBeenCalledTimes(1);

    const exploding = new CatalogProvider(MODELS);
    (exploding as unknown as { getAvailableModels: () => never }).getAvailableModels = () => {
      throw new Error('catalog blew up');
    };
    const cleanup2 = vi.fn().mockResolvedValue(undefined);
    (exploding as unknown as { cleanup: () => Promise<void> }).cleanup = cleanup2;

    expect(
      await resolveContextWindow(
        { connectionId: 'conn', modelId: 'claude-opus-5' },
        { createProviderForTurn: factoryFor(exploding) }
      )
    ).toBeUndefined();
    expect(cleanup2).toHaveBeenCalledTimes(1);
  });
});

// ABOUTME: Full-chain test that the credentialBrokerSocket supplied at initialize config flows
// through session/new → prompt → runner → exec-tool adapter into the credential tool's invocation
// envelope. Exercises the real agent process end to end; a getEffectiveConfig-in-isolation test
// would give a false green because session/new builds session config by explicit field enumeration.

import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { mkdtempSync, rmSync, writeFileSync, chmodSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import {
  AGENT_BOOT_TIMEOUT_MS,
  createE2EContext,
  spawnAgentProcess,
  withTimeout,
  defaultInitializeParams,
  E2E_TEST_TIMEOUT_MS,
} from './helpers';

// A tiny exec-tool that answers `lace-tool-schema` with a request_credential descriptor
// (declaring the credentials capability) and, on `lace-tool-invoke`, echoes back the context
// block it received as its tool result content so the test can inspect socket forwarding.
const FIXTURE_SCRIPT = `#!/usr/bin/env node
const mode = process.argv[2];
if (mode === 'lace-tool-schema') {
  process.stdout.write(JSON.stringify({
    name: 'request_credential',
    description: 'fixture credential exec-tool',
    inputSchema: { type: 'object', properties: {} },
    capabilities: ['credentials'],
  }));
  process.exit(0);
}
let buf = '';
process.stdin.on('data', (d) => { buf += d; });
process.stdin.on('end', () => {
  const env = JSON.parse(buf || '{}');
  process.stdout.write(JSON.stringify({ content: JSON.stringify(env.context ?? {}) }));
  process.exit(0);
});
`;

function makeFixtureDir(): string {
  const dir = mkdtempSync(join(tmpdir(), 'lace-cred-chain-fixture-'));
  const bin = join(dir, 'request-credential');
  writeFileSync(bin, FIXTURE_SCRIPT);
  chmodSync(bin, 0o755);
  return dir;
}

describe(
  'credentialBrokerSocket full chain (initialize → session/new → prompt → envelope)',
  { timeout: E2E_TEST_TIMEOUT_MS },
  () => {
    const ctx = createE2EContext({ prefix: 'lace-cred-chain' });
    let fixtureDir: string;

    beforeEach(() => {
      ctx.setup();
      fixtureDir = makeFixtureDir();
    });

    afterEach(async () => {
      await ctx.teardown();
      rmSync(fixtureDir, { recursive: true, force: true });
    });

    it('stamps the initialize-config broker socket into the credential tool envelope', async () => {
      ctx.agent = spawnAgentProcess({ laceDir: ctx.laceDir });

      const updates: Array<Record<string, unknown>> = [];
      ctx.agent.peer.onRequest('session/update', async (params) => {
        updates.push(params as Record<string, unknown>);
        return undefined;
      });

      await withTimeout(
        ctx.agent.peer.request('initialize', {
          ...defaultInitializeParams({
            config: {
              credentialBrokerSocket: '/tmp/x.sock',
              approvalMode: 'dangerouslySkipPermissions',
            },
          }),
          credentialToolsPaths: [fixtureDir],
        }),
        AGENT_BOOT_TIMEOUT_MS,
        'initialize'
      );

      await withTimeout(
        ctx.agent.peer.request('session/new', { cwd: ctx.workDir, mcpServers: [] }),
        5_000,
        'session/new'
      );

      const promptResult = (await withTimeout(
        ctx.agent.peer.request('session/prompt', {
          content: [{ type: 'text', text: 'request credential linear-api-key' }],
        }),
        10_000,
        'session/prompt'
      )) as { turnId: string };

      await withTimeout(
        new Promise<void>((resolve) => {
          const interval = setInterval(() => {
            const match = updates.find(
              (p) =>
                p?.type === 'tool_use' &&
                p?.name === 'request_credential' &&
                p?.status === 'completed' &&
                p?.turnId === promptResult.turnId
            );
            if (match) {
              clearInterval(interval);
              resolve();
            }
          }, 10);
        }),
        8_000,
        'tool_use stream for request_credential'
      );

      const toolUse = updates.find(
        (p) =>
          p?.type === 'tool_use' &&
          p?.name === 'request_credential' &&
          p?.status === 'completed' &&
          p?.turnId === promptResult.turnId
      );
      expect(toolUse).toBeDefined();

      const result = (toolUse?.result as { content?: Array<{ text?: string }> }) ?? {};
      const text = (result.content ?? []).map((b) => b.text ?? '').join('');
      const envelopeContext = JSON.parse(text) as Record<string, unknown>;

      expect(envelopeContext.credentialBrokerSocket).toBe('/tmp/x.sock');
    });
  }
);

// ABOUTME: Tests for sizing the preserved tail against the model's REPORTED context
// ABOUTME: size rather than the local chars/4 floor (PRI-2947). Covers the
// ABOUTME: measurement lookup, the estimator calibration scale, and the effect on
// ABOUTME: trimTailToTokenBudget / track-based compact().

import { describe, it, expect } from 'vitest';
import type { DurableEventData, TypedDurableEvent } from '@lace/agent/storage/event-types';
import {
  lastReportedContextTokens,
  estimateCurrentContextTokens,
  contextMeasurementScale,
  trimTailToTokenBudget,
  estimateTailTokens,
  splitAtTailBoundary,
} from '../toolkit';
import { compact } from '../track-compaction';
import { estimateProviderTokens } from '@lace/agent/utils/token-estimation';
import type { ProviderMessage } from '@lace/agent/providers/base-provider';

const event = (
  seq: number,
  type: DurableEventData['type'],
  data: Record<string, unknown>,
  turnId?: string
): TypedDurableEvent => ({
  eventSeq: seq,
  timestamp: `2026-08-25T00:00:${String(seq).padStart(2, '0')}Z`,
  ...(turnId ? { turnId } : {}),
  type,
  data: { type, ...data } as TypedDurableEvent['data'],
});

/** A turn whose assistant message carries `chars` characters of text. */
const sizedTurn = (
  startSeq: number,
  t: number,
  chars: number,
  lastCallInputContextTokens?: number
): TypedDurableEvent[] => {
  const turnId = `turn_${t}`;
  return [
    event(startSeq, 'prompt', {
      content: [{ type: 'text', text: `msg ${t}` }],
      track: `ext:T${t}`,
    }),
    event(startSeq + 1, 'turn_start', {}, turnId),
    event(startSeq + 2, 'message', { content: 'x'.repeat(chars) }, turnId),
    event(
      startSeq + 3,
      'turn_end',
      {
        stopReason: 'end_turn',
        usage: {
          inputTokens: 1,
          outputTokens: 1,
          ...(lastCallInputContextTokens !== undefined ? { lastCallInputContextTokens } : {}),
        },
      },
      turnId
    ),
  ];
};

const buildSession = (turnSizes: number[], measured?: number): TypedDurableEvent[] => {
  const events: TypedDurableEvent[] = [];
  let seq = 1;
  turnSizes.forEach((chars, t) => {
    // Only the newest turn carries the measurement, mirroring what a live
    // session looks like at the moment compaction runs.
    const isLast = t === turnSizes.length - 1;
    events.push(...sizedTurn(seq, t, chars, isLast ? measured : undefined));
    seq += 4;
  });
  return events;
};

// ---------------------------------------------------------------------------
// Finding the measurement in the durable log
// ---------------------------------------------------------------------------

describe('lastReportedContextTokens', () => {
  it('returns the newest turn_end’s reported context size', () => {
    const events = [...sizedTurn(1, 0, 10, 111_000), ...sizedTurn(5, 1, 10, 222_000)];
    expect(lastReportedContextTokens(events)).toBe(222_000);
  });

  it('is undefined — not zero — when no turn reported one', () => {
    // Legacy transcripts, a first turn, or a provider that reports nothing.
    // Zero would read as "empty context" and suppress compaction forever.
    const events = buildSession([10, 10]);
    expect(lastReportedContextTokens(events)).toBeUndefined();
  });

  it('ignores a measurement taken before the last compaction', () => {
    // That figure describes the pre-compaction context. Pairing it with an
    // estimate of the post-compaction event set would invent a huge scale and
    // peel the tail to nothing.
    const events = [
      ...sizedTurn(1, 0, 10, 900_000),
      event(5, 'context_compacted', { strategy: 'track-based', preserved: [] }),
      ...sizedTurn(6, 1, 10),
    ];
    expect(lastReportedContextTokens(events)).toBeUndefined();
  });
});

describe('estimateCurrentContextTokens', () => {
  it('measures the whole event stream when nothing has been compacted', () => {
    const events = buildSession([20_000, 20_000]);
    expect(estimateCurrentContextTokens(events)).toBe(
      estimateTailTokens(splitAtTailBoundary(events, 10).tail)
    );
  });

  it('counts the compaction prefix plus the events after it, not the summarized history', () => {
    // The replayed context is the preserved prefix + everything since. Counting
    // the pre-compaction events too would inflate the denominator and quietly
    // cancel the correction on any session that has compacted before.
    const preserved = [{ role: 'user', content: 'y'.repeat(4_000) }];
    const events: TypedDurableEvent[] = [
      ...sizedTurn(1, 0, 100_000),
      event(5, 'context_compacted', { strategy: 'track-based', preserved }),
      ...sizedTurn(6, 1, 8_000),
    ];
    const estimated = estimateCurrentContextTokens(events);
    // prefix 4000 chars + one 8000-char turn ≈ 3k tokens; the 100k-char turn
    // before the compaction must not be in there.
    expect(estimated).toBeLessThan(5_000);
    expect(estimated).toBeGreaterThan(2_000);
  });
});

describe('estimateProviderTokens on a malformed history', () => {
  it('counts an unrecognized content shape as no text instead of throwing', () => {
    // Calibration estimates the WHOLE log, not just the slice about to be
    // preserved, so it is the first thing to meet a history no other code path
    // ever folded. sen-core's replay of ada's real bad-state session folds to
    // entries with no `content` field at all, and the estimator's declared type
    // says that cannot happen. Throwing here takes compaction down on exactly
    // the sessions that need it most.
    const malformed = [
      { role: 'user' },
      { role: 'assistant', content: null },
      { role: 'user', content: [null, { type: 'text', text: 'abcd' }] },
    ] as unknown as ProviderMessage[];
    expect(estimateProviderTokens(malformed)).toBe(1);
  });
});

// ---------------------------------------------------------------------------
// Reconciling the measurement with the local estimate
// ---------------------------------------------------------------------------

describe('contextMeasurementScale', () => {
  it('is exactly 1 when there is no measurement', () => {
    const events = buildSession([20_000, 20_000]);
    expect(contextMeasurementScale(events, undefined)).toBe(1);
  });

  it('is the ratio by which the local estimator under-reads reality', () => {
    const events = buildSession([20_000, 20_000]);
    const estimated = estimateCurrentContextTokens(events);
    expect(contextMeasurementScale(events, estimated * 4)).toBeCloseTo(4, 5);
  });

  it('never shrinks the estimate below the local one', () => {
    // Clamped at 1 so the change can only ever make compaction size the tail
    // more truthfully, never less.
    const events = buildSession([20_000, 20_000]);
    const estimated = estimateCurrentContextTokens(events);
    expect(contextMeasurementScale(events, Math.floor(estimated / 3))).toBe(1);
  });

  it('ignores a nonsensical measurement rather than trusting it', () => {
    const events = buildSession([20_000, 20_000]);
    expect(contextMeasurementScale(events, 0)).toBe(1);
    expect(contextMeasurementScale(events, -5)).toBe(1);
    expect(contextMeasurementScale(events, Number.NaN)).toBe(1);
  });

  it('is 1 when there is nothing to calibrate against', () => {
    // No estimable text at all: the ratio would be a division by zero, and any
    // number we invented from it would be a guess.
    expect(contextMeasurementScale([], 600_000)).toBe(1);
  });
});

// ---------------------------------------------------------------------------
// The behavior PRI-2947 is about
// ---------------------------------------------------------------------------

describe('trimTailToTokenBudget with a measured context size', () => {
  it('peels turns the local estimate said would fit, when the model says otherwise', () => {
    // The bug, in one test. A short session whose durable text estimates at a
    // few thousand tokens but that the provider reports at 633K: the estimate
    // wins, nothing is peeled, and `earlier` comes back empty.
    const events = buildSession([20_000, 20_000, 20_000, 20_000, 20_000]);
    const budget = 300_000;

    const blind = trimTailToTokenBudget(events, 10, budget);
    expect(blind.earlier).toEqual([]);

    const measured = trimTailToTokenBudget(events, 10, budget, undefined, 633_419);
    expect(measured.earlier.length).toBeGreaterThan(0);
    expect(measured.tail.length).toBeLessThan(blind.tail.length);
  });

  it('reads the measurement out of the log when the caller passes none', () => {
    // /compact and ent.session.compact hold no live usage figure; the newest
    // turn_end does.
    const events = buildSession([20_000, 20_000, 20_000, 20_000, 20_000], 633_419);
    expect(trimTailToTokenBudget(events, 10, 300_000).earlier.length).toBeGreaterThan(0);
  });

  it('prefers the caller’s figure over the log’s', () => {
    // The runner's in-flight number is fresher than the last turn_end — which
    // matters most on the emergency path, where the turn that blew the window
    // has not written one yet.
    const events = buildSession([20_000, 20_000, 20_000, 20_000, 20_000], 10);
    expect(trimTailToTokenBudget(events, 10, 300_000).earlier).toEqual([]);
    expect(
      trimTailToTokenBudget(events, 10, 300_000, undefined, 633_419).earlier.length
    ).toBeGreaterThan(0);
  });

  it('leaves a healthy session alone', () => {
    // The direction that must not regress: a session the model reports as
    // comfortably inside the budget keeps its whole tail. The scaled estimate
    // of the FULL tail is the measurement itself, so "over budget" now means
    // exactly what the compaction trigger means by it.
    const events = buildSession([20_000, 20_000, 20_000, 20_000, 20_000]);
    const baseline = trimTailToTokenBudget(events, 10, 300_000);
    const healthy = trimTailToTokenBudget(events, 10, 300_000, undefined, 120_000);
    expect(healthy.tail.map((e) => e.eventSeq)).toEqual(baseline.tail.map((e) => e.eventSeq));
    expect(healthy.earlier).toEqual([]);
  });

  it('changes nothing when the measurement is absent', () => {
    const events = buildSession(Array(12).fill(20_000));
    const before = trimTailToTokenBudget(events, 10, 12_000);
    const after = trimTailToTokenBudget(events, 10, 12_000, undefined, undefined);
    expect(after.tail.map((e) => e.eventSeq)).toEqual(before.tail.map((e) => e.eventSeq));
  });

  it('does not manufacture an earlier slice out of a single-turn session', () => {
    // The peel loop bottoms out at one turn, and a one-turn split hands back
    // the leading system_prompt_set as `earlier` — non-empty, but no
    // conversation. A strategy would read that as something to summarize and
    // write a compaction that preserved the entire history verbatim, spending
    // the breakpoint that authorized it on nothing at all. That is the PRI-2945
    // wedge, and getting the tail measurement right must not walk back into it.
    const events: TypedDurableEvent[] = [
      event(1, 'system_prompt_set', { text: 'You are a test assistant.' }),
      ...sizedTurn(2, 0, 20_000),
    ];
    const trimmed = trimTailToTokenBudget(events, 10, 300_000, undefined, 633_419);
    expect(trimmed.earlier).toEqual([]);
    return compact(events, {
      threadId: 's_single',
      contextWindow: 1_000_000,
      measuredContextTokens: 633_419,
    }).then((result) => {
      expect('noop' in result).toBe(true);
    });
  });

  it('still preserves the in-flight turn when the measurement dwarfs the budget', () => {
    const events = buildSession([20_000, 20_000, 20_000]);
    const trimmed = trimTailToTokenBudget(events, 10, 1_000, undefined, 5_000_000);
    expect(trimmed.tail.length).toBe(4);
  });
});

describe('track-based compact() with a measured context size', () => {
  it('sheds history on a short session the model reports as full', () => {
    // Fewer turns than TAIL_TURNS, so the turn-count split alone yields no
    // `earlier` — the only thing that can produce one is the tail budget, and
    // before PRI-2947 the budget was compared against a number an order of
    // magnitude below reality.
    const events = buildSession([20_000, 20_000, 20_000, 20_000, 20_000]);

    return Promise.all([
      compact(events, { threadId: 's_blind', contextWindow: 1_000_000 }),
      compact(events, {
        threadId: 's_measured',
        contextWindow: 1_000_000,
        measuredContextTokens: 633_419,
      }),
    ]).then(([blind, measured]) => {
      expect('noop' in blind).toBe(true);
      expect('compactionEvent' in measured).toBe(true);
    });
  });

  it('still noops on a short session the model reports as nearly empty', () => {
    const events = buildSession([20_000, 20_000, 20_000, 20_000, 20_000]);
    return compact(events, {
      threadId: 's_healthy',
      contextWindow: 1_000_000,
      measuredContextTokens: 40_000,
    }).then((result) => {
      expect('noop' in result).toBe(true);
    });
  });
});
